template.script:
document.addEventListener('DOMContentLoaded', function () {
  var buttons = document.querySelectorAll('#wrap .hc-back-to-top');
  if (!buttons.length) return;
  var toggle = function () {
    var show = window.scrollY > 400;
    buttons.forEach(function (btn) { btn.classList.toggle('is-visible', show); });
  };
  window.addEventListener('scroll', toggle, { passive: true });
  toggle();
  buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  });
});

document.addEventListener('DOMContentLoaded', function () {
  var revealEls = document.querySelectorAll('#wrap .reveal');
  if (!revealEls.length) return;
  if ('IntersectionObserver' in window) {
    var obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          obs.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12 });
    revealEls.forEach(function (el) { obs.observe(el); });
  } else {
    revealEls.forEach(function (el) { el.classList.add('is-visible'); });
  }
});

div.script:
(function () {
  var input = document.getElementById('compras-search');
  if (!input) return;
  var cards = document.querySelectorAll('.hc-product-card[data-search-name]');
  var emptyMsg = document.getElementById('compras-sin-resultados');
  input.addEventListener('input', function () {
    var term = input.value.trim().toLowerCase();
    var visibleCount = 0;
    cards.forEach(function (card) {
      var match = !term || card.getAttribute('data-search-name').indexOf(term) !== -1;
      card.style.display = match ? '' : 'none';
      if (match) visibleCount++;
    });
    if (emptyMsg) emptyMsg.style.display = visibleCount === 0 ? '' : 'none';
  });
})();

document.addEventListener('keydown', function (e) {
  if (e.key === 'Escape') {
    var lb = document.getElementById('lightbox');
    if (lb) lb.classList.remove('open');
  }
});

document.addEventListener('DOMContentLoaded', function () {
  var openBtn = document.getElementById('pedido-open-btn');
  var overlay = document.getElementById('pedido-modal-overlay');
  if (openBtn && overlay) {
    openBtn.addEventListener('click', function () { overlay.classList.add('open'); });
  }
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && overlay) overlay.classList.remove('open');
  });
});

(function () {
  var root = document.querySelector('.historia-page');
  if (!root) return;

  var toggle = document.getElementById('historia-theme-toggle');
  if (toggle) {
    var saved = null;
    try { saved = localStorage.getItem('historia-theme'); } catch (e) {}
    if (saved === 'dark') {
      root.setAttribute('data-theme', 'dark');
      toggle.textContent = '☀️';
    }
    toggle.addEventListener('click', function () {
      var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      toggle.textContent = next === 'dark' ? '☀️' : '🌙';
      try { localStorage.setItem('historia-theme', next); } catch (e) {}
    });
  }

  // Contadores animados de las stats (+40, +500, +150, 6): cuentan
  // desde 0 hasta el valor real la primera vez que entran en pantalla.
  var statEls = root.querySelectorAll('.historia-stat-value');
  if (statEls.length && 'IntersectionObserver' in window) {
    var animateCount = function (el) {
      var target = el.getAttribute('data-target') || '';
      var match = target.match(/^(\D*)(\d+)(\D*)$/);
      if (!match) return; // sin dígitos, se deja el texto tal cual
      var prefix = match[1], endNum = parseInt(match[2], 10), suffix = match[3];
      var duration = 1200, startTime = null;
      var step = function (timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / duration, 1);
        el.textContent = prefix + Math.floor(progress * endNum) + suffix;
        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = target; // valor final exacto, sin redondeos
        }
      };
      window.requestAnimationFrame(step);
    };
    var statsObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          animateCount(entry.target);
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.4 });
    statEls.forEach(function (el) { statsObserver.observe(el); });
  }
})();
